def make(i, row):
    tag, prompt, opts, answer, reason = row
    options = [{'id': chr(65+j), 'text': t} for j, t in enumerate(opts)]
    aid = next(o['id'] for o in options if o['text'] == answer)
    steps = [f'讀題定位：圈出「{tag}」與題目中的速度、方向、合力或外力條件。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」符合慣性與合力為零的判斷。', '排除誘答：分清合力為零與完全無力、速率與速度、慣性與造成運動改變的外力。', '最後回查：確認答案有保留題幹的時間、測量誤差與受力條件，沒有過度推論。']
    return {'id': f'question-science-content-eb-iv-10-{i}', 'subject': 'science', 'type': 'single-choice', 'prompt': prompt, 'options': options, 'knowledgeIds': ['kg-science-content-eb-iv-10'], 'difficulty': 'medium', 'answer': {'value': aid, 'explanation': reason}, 'provenance': {'origin': 'original', 'license': 'All rights reserved', 'sourceUrl': URL, 'sourceLocator': '公立國中段考自然科；研究慣性、合力為零、等速運動與資料判讀的能力方向。', 'authoringNote': '依官方課綱 KG 與公立國中公開試題能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}, 'reviewStatus': 'draft', 'updatedAt': '2026-09-08', 'lessonId': 'lesson-science-content-eb-iv-10', 'examPatternRefs': [{'url': URL, 'title': '公立國中段考自然科；僅研究題型與能力方向，未複製原題。', 'year': '114', 'subject': 'science', 'locator': '不受力物體維持原有運動狀態', 'observedPattern': '能力方向研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'}], 'solutionStrategy': '先判斷速度大小與方向是否改變，再由合力與外力分析慣性運動。', 'solutionSteps': steps}

